.bespoke-slide, .bespoke-slide * { box-sizing: border-box; }
.bespoke-slide { position: relative; isolation: isolate; min-height: 360px; padding: clamp(1.35rem, 4vw, 3.5rem); color: var(--role-body); background-color: var(--role-content-background); font-family: var(--font-body); overflow-wrap: anywhere; }
.bespoke-slide .slide-body, body, .slide p, .card p, .content-list li, .chapter-label { font-family: var(--font-body); }
.bespoke-slide .slide-heading, .bespoke-slide .slide-title-text, .bespoke-slide .slide-card h3, .slide-title h1, .slide h2, .slide h3, .card h4, .smart-content h4, .matrix-action, .slide-section h2 { font-family: var(--font-heading); font-weight: 400; }
.bespoke-slide :is(.slide-sidebar, .slide-sidebar-drawer, .slide-sidebar-disclosure > summary), .sidebar, .sidebar-toggle { background: var(--role-sidebar); color: var(--role-sidebar-ink); }
.sidebar .sidebar-title, .sidebar .resources-title, .sidebar .chapter-header, .sidebar .slide-item, .sidebar .resource-link { color: var(--role-sidebar-ink); }
.sidebar .chapter-header:hover, .sidebar .slide-item:hover, .sidebar .resource-link:hover { color: var(--role-sidebar-ink); background: transparent; text-decoration: underline; }
.sidebar .slide-item.active, .sidebar .chapter-item.active > .chapter-header { color: var(--role-sidebar-ink); background: transparent; border-left-color: var(--role-accent); box-shadow: inset 3px 0 0 var(--role-accent); }
.bespoke-slide[data-kind="cards"], .bespoke-slide[data-kind="video"], .bespoke-slide[data-kind="activity"] { container-type:inline-size; display:grid; grid-template-columns:min(280px,100%) minmax(0,1fr); padding:0; min-height:480px; align-items:stretch; align-content:start; }
.bespoke-slide .slide-content { min-width:0; container-type:inline-size; padding:clamp(1.25rem,3cqw,3rem); }
.bespoke-slide :is(.slide-sidebar, .slide-sidebar-drawer) { padding:2rem min(1.5rem,24px); font-family:var(--font-body); font-size:.85rem; line-height:1.45; display:flex; flex-direction:column; gap:1rem; min-width:0; }
.bespoke-slide .sample-sidebar-title { margin:0; font-size:.875rem; font-weight:600; text-transform:uppercase; letter-spacing:.08em; padding-bottom:1rem; border-bottom:1px solid currentColor; }
.bespoke-slide .sample-sidebar-note { font-size:.75rem; }
.bespoke-slide .sample-chapters { display:flex; flex-direction:column; gap:.25rem; list-style:none; padding:0; margin:0; }
.bespoke-slide .sample-chapter { display:flex; align-items:center; gap:.5rem; padding:.65rem .5rem; border-left:3px solid transparent; border-radius:.5rem; font-size:.85rem; }
.bespoke-slide .sample-chapter[data-current] { border-left-color:var(--role-accent); font-weight:700; }
.bespoke-slide .sample-chapter svg { width:.6rem; height:.6rem; flex-shrink:0; }
.bespoke-slide .sample-badge { font-size:.65rem; font-weight:700; border-radius:.25rem; padding:.15rem .4rem; flex-shrink:0; }
.bespoke-slide .sample-badge[data-badge="w"] { background:var(--gold);color:var(--royal); }
.bespoke-slide .sample-badge[data-badge="i"] { background:var(--primary);color:var(--light); }
.bespoke-slide .sample-badge[data-badge="p"] { background:var(--accent);color:var(--royal); }
.bespoke-slide .sample-badge[data-badge="e"] { background:var(--gold);color:var(--royal); }
.bespoke-slide .sample-badge[data-badge="a"] { background:var(--dark);color:var(--light); }
.bespoke-slide .sample-slide-name { display:block; margin:.15rem 0 .5rem 1rem; padding:.4rem .65rem; border-left:3px solid var(--role-accent); font-size:.8rem; }
.bespoke-slide .sample-resources { margin-top:auto; padding-top:1rem; border-top:1px solid currentColor; display:grid; gap:.5rem; font-size:.8rem; }
.bespoke-slide .sample-resources strong { font-size:.75rem; text-transform:uppercase; letter-spacing:.08em; }
.bespoke-slide .sample-slide-counter { padding-top:1rem; border-top:1px solid currentColor; font-size:.75rem; }
.bespoke-slide .slide-sidebar-disclosure { display:none; min-width:0; }
.bespoke-slide .slide-sidebar-disclosure > summary { list-style:none; display:flex; align-items:center; gap:.5rem; width:fit-content; max-width:100%; min-height:44px; padding:.65rem .8rem; border-radius:.35rem; cursor:pointer; font-size:.85rem; }
.bespoke-slide .slide-sidebar-disclosure > summary::-webkit-details-marker { display:none; }
.bespoke-slide .slide-sidebar-disclosure > summary svg { width:20px; height:20px; flex-shrink:0; }
.bespoke-slide .slide-sidebar-disclosure > summary:focus-visible { outline:3px solid var(--role-sidebar-ink); outline-offset:-5px; }
.bespoke-slide .slide-sidebar-drawer { position:absolute; z-index:3; top:3.75rem; left:0; width:min(17.5rem,100%); max-height:calc(100% - 3.75rem); overflow-y:auto; box-shadow:4px 6px 14px rgba(0,0,0,.2); }
.bespoke-slide .slide-sidebar-drawer:focus-visible { outline:3px solid var(--role-sidebar-ink); outline-offset:-5px; }
.bespoke-slide .slide-heading, .slide:not(.slide-title):not(.slide-section) h2, .card h4 { color: var(--role-heading); }
.bespoke-slide .slide-body, .slide:not(.slide-title):not(.slide-section) p, .content-list li, .card p { color: var(--role-body); line-height: 1.55; }
.bespoke-slide .slide-accent, .divider { background: var(--role-accent); }
.bespoke-slide .slide-button, .download-btn, .video-btn { background: var(--role-button); color: var(--role-button-ink); border: 0; border-radius: .4rem; padding: .65rem 1.1rem; font-family: var(--font-body); font-size: 1rem; line-height: 1.4; min-height: 44px; }
.bespoke-slide .slide-logo { font-family: var(--font-body); font-weight: 600; letter-spacing: .14em; font-size: .85rem; margin-bottom: 2rem; }
.bespoke-slide img.slide-logo { display:block; width:5rem; height:5rem; object-fit:contain; background:var(--light); border-radius:.4rem; padding:.4rem; }
.bespoke-slide[data-kind="title"], .slide-title { container-type:inline-size; box-sizing:border-box; width:100%; min-width:0; max-width:100%; min-height:420px; height:auto; overflow:visible; position:relative; padding: 112px 6% 32px; grid-template-columns:minmax(0,1fr); column-gap:0; grid-template-rows:minmax(0,1fr) repeat(5,auto) minmax(0,1fr); justify-items:start; align-items:start; align-content:stretch; text-align:left; background-color:var(--role-title-background); background-image:radial-gradient(circle, rgba(0, 19, 63, 0.2) 2.5px, transparent 3px); background-size:24px 24px; background-position:left top; background-repeat:repeat; }
.bespoke-slide[data-kind="title"], .slide-title.active { display:grid; }
.bespoke-slide[data-kind="title"]::before, .slide-title.active::before { content:'';display:block;grid-column:1 / -1;grid-row:1 / 8;height:max(276px,calc(100cqw / .88 * 9 / 16 - 144px));min-width:0;justify-self:stretch;pointer-events:none;visibility:hidden; }
.slide-title.active::after{content:none;display:none;}
.bespoke-slide[data-kind="title"] .slide-title-text, .slide-title h1 { grid-column:1; grid-row:3; min-width:0; max-width:20ch; color:var(--role-title-text); font-size:clamp(1.5rem,4.8cqw,3.7rem); line-height:1.12; margin:0 0 16px; overflow-wrap:anywhere; }
.bespoke-slide[data-kind="title"] .slide-subtitle, .slide-title .subtitle { grid-column:1; grid-row:5; min-width:0; max-width:42ch; color:var(--role-subtitle); font-family:var(--font-body); font-size:clamp(1rem,1.8cqw,1.25rem); line-height:1.5; margin:0; overflow-wrap:anywhere; }
.bespoke-slide[data-kind="title"] .slide-logo, .slide-title .logo { grid-column:1; grid-row:2; width:clamp(48px,7cqw,80px); height:clamp(48px,7cqw,80px); max-width:100%; box-sizing:border-box; object-fit:contain; background:var(--light); color:var(--royal); border-radius:.4rem; padding:.4rem; font-size:.7rem; letter-spacing:0; display:grid; place-items:center; position:absolute;top:24px;right:6%;margin:0;grid-area:auto; }
.bespoke-slide[data-kind="title"] .slide-accent, .slide-title .divider { grid-column:1; grid-row:4; width:clamp(40px,8cqw,80px); height:4px; margin:0 0 16px; background:var(--role-accent); }
.slide-title .copyright{grid-column:1;grid-row:6;color:var(--role-subtitle);font-family:var(--font-body);font-size:.85rem;line-height:1.5;margin:16px 0 0;}
.bespoke-slide[data-kind="divider"], .slide-section, .slide-section[data-chapter-num] { container-type:inline-size; background-color:var(--role-divider-background); background-image:radial-gradient(circle, rgba(0, 19, 63, 0.2) 2.5px, transparent 3px); background-size:24px 24px; background-position:left top; background-repeat:repeat; color:var(--role-subtitle); text-align:left; align-items:flex-start; position:relative; }
.bespoke-slide[data-kind="divider"] { display:flex; flex-direction:column; justify-content:center; }
.bespoke-slide[data-kind="divider"] .slide-heading, .slide-section h2 { color:var(--role-title-text); position:relative; z-index:1; }
.bespoke-slide[data-kind="divider"] .slide-body, .slide-section p, .slide-section .chapter-label { color:var(--role-subtitle); position:relative; z-index:1; }
.bespoke-slide .slide-watermark, .slide-section::after { display:block; position:absolute; right:6%; top:5%; max-width:88%; max-height:90%; overflow:hidden; white-space:nowrap; transform:none; font-size:min(9rem,42cqw); line-height:1; color:var(--role-title-text); opacity:.12; pointer-events:none; }
.bespoke-slide[data-kind="cards"], .bespoke-slide[data-kind="video"], .bespoke-slide[data-kind="activity"], .slide:not(.slide-title):not(.slide-section) { background-color:var(--role-content-background); background-image:radial-gradient(circle, rgba(0, 19, 63, 0.2) 2.5px, transparent 3px); background-size:24px 24px; background-position:left top; background-repeat:repeat; }
.main {background-color:var(--role-content-background);background-image:none;}
.bespoke-slide .slide-card, .bespoke-slide .slide-title-bar, .bespoke-slide .slide-activity, .bespoke-slide .slide-heading, .slide:not(.slide-title):not(.slide-section) h2, .slide:not(.slide-title):not(.slide-section) h3, .slide:not(.slide-title):not(.slide-section) p, .slide:not(.slide-title):not(.slide-section) li { background-color:var(--role-content-background); }
.bespoke-slide[data-kind="divider"] .slide-heading { background:transparent; }
.bespoke-slide[data-kind="cards"], .slide { container-type:inline-size; }
.slide.active{justify-content:safe center;}
.bespoke-slide .slide-cards, .cards-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:1rem; align-items:stretch; }
.bespoke-slide .slide-card, .card { min-width:0; overflow-wrap:anywhere; background:var(--role-content-background); color:var(--role-body); padding:1.1rem; border-radius:.3rem; border:0; box-shadow:none; }
.bespoke-slide .slide-card, .card { border-left:5px solid var(--role-accent); }
.bespoke-slide .slide-card h3, .card h4 { color:var(--role-heading); margin:0 0 .6rem; font-size:1.25rem; }
.bespoke-slide .slide-card .slide-body { margin:0; font-size:.92rem; }
.bespoke-slide .slide-card li, .content-list li { color:var(--role-body); }
.bespoke-slide .slide-card ul, .bespoke-slide .slide-card ol { padding-left:1.2rem; }
.bespoke-slide .slide-title-bar { padding: .8rem 0; margin:0 0 1rem; border-bottom:3px solid var(--role-accent); }
.bespoke-slide .slide-title-bar .slide-heading { margin:0; }
.bespoke-slide .slide-heading { font-size:clamp(1.55rem,3vw,2.25rem); margin:0 0 1rem; line-height:1.2; }
.bespoke-slide .slide-video-frame, .video-container { box-sizing:border-box; width:100%; max-width:100%; aspect-ratio:16/9; min-width:0; min-height:0; overflow:hidden; background:var(--light); color:var(--role-sidebar-ink); border:6px solid var(--role-accent); padding:2px; outline:2px solid var(--light); outline-offset:-2px; box-shadow:none; display:grid; grid-template: minmax(0,1fr) / minmax(0,1fr); place-items:stretch; border-radius:.5rem; }
.bespoke-slide .slide-video-frame > span, .video-container > video, .video-container > iframe { position:static; display:block; box-sizing:border-box; width:100%; height:100%; min-width:0; min-height:0; max-width:100%; background:var(--role-sidebar); object-fit:contain; border:0; border-radius:0!important; box-shadow:none!important; }
.bespoke-slide .slide-video-frame > span { display:grid; place-items:center; }
.bespoke-slide[data-kind="video"] .slide-heading, .slide-video h2 { font-size:2rem; text-transform:none; letter-spacing:normal; }
.bespoke-slide .slide-activity, .activity-box { padding:1.5rem; border:2px solid var(--role-accent); border-radius:.5rem; background:var(--role-content-background); }
.bespoke-slide .slide-activity, .activity-box { border:0; border-left:6px solid var(--role-accent); border-radius:0; }
.bespoke-slide .slide-activity-label, .activity-label { font-family:var(--font-body); color:var(--role-heading); font-size:.95rem; text-transform:uppercase; }
@media(max-width:600px) { .bespoke-slide {padding:1.25rem;min-height:300px;} .bespoke-slide .slide-cards {grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem;} .bespoke-slide .slide-card {padding:.8rem;} .bespoke-slide .slide-video-layout,.bespoke-slide .slide-activity {grid-template-columns:1fr;} }
@container(max-width:38rem){.bespoke-slide .slide-cards, .cards-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@container(max-width:22rem){.bespoke-slide .slide-cards, .cards-grid{grid-template-columns:minmax(0,1fr);}}
@container(max-width:40rem){.bespoke-slide .slide-sidebar{display:none;}.bespoke-slide .slide-sidebar-disclosure{display:block;grid-column:1 / -1;margin:1rem 1.25rem 0;}.bespoke-slide .slide-content{grid-column:1 / -1;}}
@container(max-width:30rem){.bespoke-slide .slide-video-layout,.bespoke-slide .slide-activity{grid-template-columns:minmax(0,1fr);}}
.bespoke-slide[data-kind="title"], .slide-title{background-color:#ffffff!important;background-image:radial-gradient(circle, rgba(255, 255, 255, 0.30000000000000004) 2.5px, transparent 3px), linear-gradient(135deg in srgb, #ffffff, #edf3f7)!important;background-size:24px 24px, 100% 100%!important;background-position:left top, center!important;background-repeat:repeat, no-repeat!important;}
.bespoke-slide[data-kind="title"] .slide-title-text, .slide-title h1{min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="title"] .slide-subtitle, .slide-title :is(.subtitle,.copyright){min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="cards"], .slide:not(.slide-video):not(.slide-section):has(.cards-grid){background-color:#a7253f!important;background-image:radial-gradient(circle, rgba(255, 255, 255, 0.1) 2.5px, transparent 3px)!important;background-size:24px 24px!important;background-position:left top!important;background-repeat:repeat!important;}
.bespoke-slide[data-kind="cards"] :is(.slide-card,.slide-title-bar,.slide-activity,.slide-heading), .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(.card,.activity-box,h2,h3,h4,p,li){background-color:transparent;background-image:none;}
.bespoke-slide[data-kind="cards"] :is(.slide-heading,.slide-card h3), .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(h2,h3,h4){min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="cards"] .slide-card .slide-body, .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(p,li){min-width:0;overflow-wrap:anywhere}

