@container(max-width:40rem){.bespoke-slide .slide-sidebar{display:none;}.bespoke-slide .slide-sidebar-disclosure{display:block;grid-column:1 / -1;margin:1rem 1.25rem 0;}.bespoke-slide .slide-content{grid-column:1 / -1;}}
@container(max-width:30rem){.bespoke-slide .slide-video-layout,.bespoke-slide .slide-activity{grid-template-columns:minmax(0,1fr);}}
.bespoke-slide[data-kind="title"], .slide-title{background-color:#ffffff!important;background-image:linear-gradient(135deg, rgba(255, 255, 255, 0.36), rgba(255, 255, 255, 0) 75%), linear-gradient(135deg in srgb, #ffffff, #edf3f7)!important;background-size:100% 100%, 100% 100%!important;background-position:left top, center!important;background-repeat:repeat, no-repeat!important;}
.bespoke-slide[data-kind="title"] .slide-title-text, .slide-title h1{min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="title"] .slide-subtitle, .slide-title :is(.subtitle,.copyright){min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="cards"], .slide:not(.slide-video):not(.slide-section):has(.cards-grid){background-color:#a7253f!important;background-image:linear-gradient(135deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0) 75%)!important;background-size:100% 100%!important;background-position:left top!important;background-repeat:repeat!important;}
.bespoke-slide[data-kind="cards"] :is(.slide-card,.slide-title-bar,.slide-activity,.slide-heading), .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(.card,.activity-box,h2,h3,h4,p,li){background-color:transparent;background-image:none;}
.bespoke-slide[data-kind="cards"] :is(.slide-heading,.slide-card h3), .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(h2,h3,h4){min-width:0;overflow-wrap:anywhere}
.bespoke-slide[data-kind="cards"] .slide-card .slide-body, .slide:not(.slide-video):not(.slide-section):has(.cards-grid) :is(p,li){min-width:0;overflow-wrap:anywhere}
